def O(k, i, code, text, acts):
    return {"id": f"{k}_o{i}", "code": code, "text": text, "selected": True, "suffix": "", "activities": [
        {"time45": a[0], "time90": a[1], "teacher": a[2], "student": a[3], "eval": a[4]} for a in acts]}

def R(phase, strat, mins, objs, teacher, student, tool, q, ans, crit):
    return [phase, strat, mins, objs, teacher, student, {"tool": tool, "q": q, "ans": ans, "crit": crit}]

def L(code, title, objectives, **kw):
    d = {"course": C, "sem": S, "unitNum": N, "unitTitle": U, "unitShort": SHORT, "code": code, "title": title,
         "defaultDuration": 45, "objectives": objectives}
    d.update(kw); return d

